// Artwork provenance: C2PA Content Credentials on a page's images (owner 2026-11-17).
//
// Evidence only. It records who signed an image's Content Credentials and whether they mark it as
// AI-generated, so a takedown file can say e.g. "this site's artwork was generated by OpenAI's image
// service, per its signed credentials". It never changes the risk score: legitimate sites use AI
// images too, and most sites carry no credentials at all (2026-11-16 survey: 0 of 332 images on 41
// official brand sites, 21 of 960 on 184 lookalikes).
//
// What it does and does not check:
// - Reads the embedded C2PA manifest (JPEG APP11/JUMBF, PNG caBX, WebP C2PA chunk, ISO-BMFF jumb) and
//   the X.509 certificates inside it: the signing (leaf) certificate's subject and issuer.
// - Does NOT validate the signature cryptographically and does NOT check the C2PA trust list. Every
//   record says so (`signature_validated: false`).
// - An IPTC/XMP "DigitalSourceType" AI label without a signature is recorded separately, as weaker.
// - No credentials found never means "authentic" or "human-made".
// Image bytes are never kept: only the URL, SHA-256, format and the fields above.
"use strict";

const checks = require("./checks");

const METHOD = "bp-provenance/1";
const MAX_IMAGES = 4;
const ARTWORK_BUDGET_MS = 10_000; // the whole step; keeps the 40 s re-check deadline safe
const IMAGE_MAX_BYTES = 2 * 1024 * 1024; // a PNG's caBX chunk can sit after large image data
const LIMITS = [
  "Signatures are read, not cryptographically validated, and signers are not checked against the C2PA trust list.",
  "No Content Credentials does not mean an image is authentic or human-made: most sites never add them, and many hosts strip them.",
  "AI-generated artwork is not by itself a sign of fraud and does not change the risk score.",
];

const IMG_RES = [
  // og:image, og:image:url, og:image:secure_url, twitter:image(:src) only: not og:image:alt, :width, :type.
  /<meta\b[^>]*["'](?:og:image(?::url|:secure_url)?|twitter:image(?::src)?)["'][^>]*\bcontent\s*=\s*["']([^"']+)/gi,
  /<meta\b[^>]*\bcontent\s*=\s*["']([^"']+)["'][^>]*["'](?:og:image(?::url|:secure_url)?|twitter:image(?::src)?)["']/gi,
  /<img\b[^>]*?\bsrc\s*=\s*["']([^"']+)/gi,
  /\bsrcset\s*=\s*["']([^"'\s,]+)/gi,
  /<link\b[^>]*\brel\s*=\s*["'][^"']*\bicon\b[^"']*["'][^>]*\bhref\s*=\s*["']([^"']+)/gi,
];

// Pure: up to `max` absolute http(s) image URLs, social-card images first. SVG and data: URLs skipped.
function imageUrls(html, baseUrl, max = MAX_IMAGES) {
  const seen = new Set();
  const out = [];
  for (const re of IMG_RES) {
    for (const m of html.matchAll(re)) {
      const raw = m[1].trim().replace(/&amp;/g, "&");
      if (!raw || raw.startsWith("data:")) continue;
      let u;
      try { u = new URL(raw, baseUrl); } catch { continue; }
      if (u.protocol !== "http:" && u.protocol !== "https:") continue;
      if (/\.svg$/i.test(u.pathname)) continue;
      const s = u.toString();
      if (seen.has(s)) continue;
      seen.add(s);
      out.push(s);
      if (out.length >= max) return out;
    }
  }
  return out;
}

function imageFormat(b) {
  if (b.length >= 2 && b[0] === 0xff && b[1] === 0xd8) return "jpeg";
  if (b.length >= 8 && b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return "png";
  if (b.length >= 12 && b.toString("latin1", 0, 4) === "RIFF" && b.toString("latin1", 8, 12) === "WEBP") return "webp";
  if (b.length >= 8 && b.toString("latin1", 4, 8) === "ftyp") return "bmff";
  if (b.length >= 3 && b.toString("latin1", 0, 3) === "GIF") return "gif";
  return "other";
}

// Pure: the C2PA manifest bytes in an image, and whether the search covered the whole container
// (`complete: false` means the read was cut short before the manifest could have appeared).
function manifestRegion(b, fmt, truncated) {
  if (fmt === "jpeg") {
    let i = 2;
    const parts = [];
    while (i + 4 <= b.length && b[i] === 0xff) {
      const marker = b[i + 1];
      if (marker === 0xda || marker === 0xd9) return { region: parts.length ? Buffer.concat(parts) : null, complete: true };
      const len = b.readUInt16BE(i + 2);
      const seg = b.subarray(i + 4, i + 2 + len);
      if (marker === 0xeb && (seg.includes("jumb") || seg.includes("c2pa"))) parts.push(seg);
      i += 2 + len;
    }
    return { region: parts.length ? Buffer.concat(parts) : null, complete: !truncated };
  }
  if (fmt === "png") {
    let i = 8;
    while (i + 8 <= b.length) {
      const len = b.readUInt32BE(i);
      const type = b.toString("latin1", i + 4, i + 8);
      if (type === "caBX") return { region: b.subarray(i + 8, i + 8 + len), complete: true };
      if (type === "IEND") return { region: null, complete: true };
      i += 12 + len;
    }
    return { region: null, complete: !truncated };
  }
  if (fmt === "webp") {
    let i = 12;
    while (i + 8 <= b.length) {
      const type = b.toString("latin1", i, i + 4);
      const len = b.readUInt32LE(i + 4);
      if (type === "C2PA") return { region: b.subarray(i + 8, i + 8 + len), complete: true };
      i += 8 + len + (len & 1);
    }
    return { region: null, complete: !truncated };
  }
  if (fmt === "bmff") {
    const j = b.indexOf("jumb");
    if (j >= 0 && b.subarray(j, j + 4096).includes("c2pa")) return { region: b.subarray(j), complete: true };
    return { region: null, complete: !truncated };
  }
  return { region: null, complete: true };
}

// --- Minimal DER reading: certificate subject/issuer names, CA and time-stamping flags ----------

function tl(b, p) {
  if (p + 2 > b.length) return null;
  const tag = b[p];
  let len = b[p + 1];
  let hdr = 2;
  if (len & 0x80) {
    const n = len & 0x7f;
    if (n < 1 || n > 3 || p + 2 + n > b.length) return null;
    len = 0;
    for (let k = 0; k < n; k++) len = len * 256 + b[p + 2 + k];
    hdr = 2 + n;
  }
  const end = p + hdr + len;
  if (end > b.length) return null;
  return { tag, start: p + hdr, end };
}

const OID_CN = Buffer.from([0x06, 0x03, 0x55, 0x04, 0x03]);
const OID_O = Buffer.from([0x06, 0x03, 0x55, 0x04, 0x0a]);
const OID_BASIC_CONSTRAINTS = Buffer.from([0x06, 0x03, 0x55, 0x1d, 0x13]);
const OID_TIMESTAMPING = Buffer.from([0x06, 0x08, 0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x08]);
const OID_OCSP_SIGNING = Buffer.from([0x06, 0x08, 0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x09]);
const STRING_TAGS = new Set([0x0c, 0x13, 0x14, 0x16, 0x1e]);

function nameField(name, oid) {
  const j = name.indexOf(oid);
  if (j < 0) return null;
  const v = tl(name, j + oid.length);
  if (!v || !STRING_TAGS.has(v.tag)) return null;
  const raw = name.subarray(v.start, v.end);
  const text = v.tag === 0x1e ? Buffer.from(raw).swap16().toString("utf16le") : raw.toString("utf8");
  return text.replace(/[\u0000-\u001f]/g, "").slice(0, 120) || null;
}

function parseName(b, node) {
  const name = b.subarray(node.start, node.end);
  return { cn: nameField(name, OID_CN), o: nameField(name, OID_O) };
}

// One certificate starting at p, or null. Returns the subject, issuer, flags and where it ends.
function parseCert(b, p) {
  const cert = tl(b, p);
  if (!cert || cert.tag !== 0x30) return null;
  const tbs = tl(b, cert.start);
  if (!tbs || tbs.tag !== 0x30 || tbs.end > cert.end) return null;
  let q = tbs.start;
  let node = tl(b, q);
  if (node && node.tag === 0xa0) { q = node.end; node = tl(b, q); }
  if (!node || node.tag !== 0x02) return null; // serial
  const alg = tl(b, node.end);
  if (!alg || alg.tag !== 0x30) return null;
  const issuer = tl(b, alg.end);
  if (!issuer || issuer.tag !== 0x30) return null;
  const validity = tl(b, issuer.end);
  if (!validity || validity.tag !== 0x30) return null;
  const subject = tl(b, validity.end);
  if (!subject || subject.tag !== 0x30 || subject.end > tbs.end) return null;
  const tbsBytes = b.subarray(tbs.start, tbs.end);
  return {
    subject: parseName(b, subject),
    issuer: parseName(b, issuer),
    is_ca: basicConstraintsCa(tbsBytes),
    is_timestamp: tbsBytes.includes(OID_TIMESTAMPING),
    is_ocsp: tbsBytes.includes(OID_OCSP_SIGNING),
    end: cert.end,
  };
}

// basicConstraints: Extension ::= SEQUENCE { OID, critical BOOLEAN OPTIONAL, OCTET STRING { SEQUENCE { cA BOOLEAN ... } } }.
// The critical flag is also 01 01 ff, so read the cA value from inside the OCTET STRING only.
function basicConstraintsCa(tbsBytes) {
  const j = tbsBytes.indexOf(OID_BASIC_CONSTRAINTS);
  if (j < 0) return false;
  let p = j + OID_BASIC_CONSTRAINTS.length;
  let node = tl(tbsBytes, p);
  if (node && node.tag === 0x01) node = tl(tbsBytes, node.end);
  if (!node || node.tag !== 0x04) return false;
  const seq = tl(tbsBytes, node.start);
  if (!seq || seq.tag !== 0x30 || seq.start === seq.end) return false;
  const first = tl(tbsBytes, seq.start);
  return !!first && first.tag === 0x01 && tbsBytes[first.start] !== 0x00;
}

function certificates(region) {
  const out = [];
  for (let p = 0; p + 4 < region.length; ) {
    if (region[p] === 0x30 && region[p + 1] === 0x82 && region[p + 4] === 0x30) {
      const c = parseCert(region, p);
      if (c && (c.subject.cn || c.subject.o)) {
        out.push(c);
        p = c.end;
        continue;
      }
    }
    p++;
  }
  return out;
}

const AI_SOURCE_RE = /(compositeWithTrainedAlgorithmicMedia|trainedAlgorithmicMedia)/;
const ACTION_RE = /c2pa\.(created|opened|edited|converted|placed|published|resized|cropped|color_adjustments|transcoded|repackaged)/g;
const XMP_AI_RE = /DigitalSourceType[^<>]{0,200}?(compositeWithTrainedAlgorithmicMedia|trainedAlgorithmicMedia)/;
const TEST_CERT_RE = /self-signed|ephemeral|local use only|\btest\b/i;

// Pure: the derived fields for one image's bytes.
function inspectImage(b, truncated = false) {
  const format = imageFormat(b);
  const { region, complete } = manifestRegion(b, format, truncated);
  const rec = { format, searched: complete ? "whole_file" : "first_bytes_only", content_credentials: !!region };
  const xmp = XMP_AI_RE.exec(b.toString("latin1", 0, Math.min(b.length, 512 * 1024)));
  if (!region) {
    if (xmp) rec.unsigned_ai_label = xmp[1];
    return rec;
  }
  const text = region.toString("latin1");
  // The claim signer: an end-entity certificate that isn't a time-stamping or OCSP one. With
  // ingredient manifests there can be several; the active manifest is stored last, so take the last.
  const leaves = certificates(region).filter((c) => !c.is_ca && !c.is_timestamp && !c.is_ocsp);
  const leaf = leaves.length ? leaves[leaves.length - 1] : null;
  rec.signer = leaf ? leaf.subject : null;
  rec.signer_issuer = leaf ? leaf.issuer : null;
  rec.test_certificate = !!leaf && (TEST_CERT_RE.test(`${leaf.subject.o || ""} ${leaf.subject.cn || ""} ${leaf.issuer.o || ""}`) ||
    (leaf.subject.cn === leaf.issuer.cn && leaf.subject.o === leaf.issuer.o));
  const ai = AI_SOURCE_RE.exec(text);
  rec.ai_generated = !!ai;
  if (ai) rec.digital_source_type = ai[1];
  rec.actions = [...new Set([...text.matchAll(ACTION_RE)].map((m) => m[1]))].sort();
  return rec;
}

// "OpenAI OpCo, LLC (OpenAI Media Service)". A self-signed test certificate's organisation is
// boilerplate ("Self-signed ephemeral certificate ..."), so it is named by its common name instead.
function signerName(s, test = false) {
  if (!s) return "an unnamed signer";
  if (test) return `${s.cn || s.o} (self-signed test certificate, not a trusted signer)`;
  if (s.o && s.cn && s.o !== s.cn) return `${s.o} (${s.cn})`;
  return s.o || s.cn;
}

// Pure: the plain-language line a takedown file can quote.
function statement(images) {
  const read = images.filter((i) => i.format);
  if (!read.length) return "No page images could be read.";
  const n = read.length;
  const of = (k) => `${k} of ${n} image${n === 1 ? "" : "s"} checked on this page ${k === 1 ? "carries" : "carry"}`;
  const signedAi = read.filter((i) => i.content_credentials && i.ai_generated);
  const parts = [];
  if (signedAi.length) {
    const names = [...new Set(signedAi.map((i) => signerName(i.signer, i.test_certificate)))];
    parts.push(`${of(signedAi.length)} C2PA Content Credentials marking ${signedAi.length === 1 ? "it" : "them"} as AI-generated, signed by ${names.join("; ")}.`);
  }
  const signedOther = read.filter((i) => i.content_credentials && !i.ai_generated);
  if (signedOther.length) {
    const names = [...new Set(signedOther.map((i) => signerName(i.signer, i.test_certificate)))];
    parts.push(`${of(signedOther.length)} C2PA Content Credentials with no AI-generated mark, signed by ${names.join("; ")}.`);
  }
  const labels = read.filter((i) => !i.content_credentials && i.unsigned_ai_label);
  if (labels.length) parts.push(`${of(labels.length)} an unsigned IPTC label marking ${labels.length === 1 ? "it" : "them"} as AI-generated.`);
  if (!parts.length) return `None of the ${n} image${n === 1 ? "" : "s"} checked on this page carries Content Credentials or an AI label.`;
  return `${parts.join(" ")} Signatures were read, not validated.`;
}

// Live: fetch up to MAX_IMAGES page images (same SSRF guard and size cap as the homepage; robots.txt
// honoured on other hosts) and summarise. Never throws; a failed image is recorded as such.
async function artwork(html, pageUrl, opts = {}) {
  const fetchVetted = opts.fetchVetted || checks.fetchVetted;
  const urls = imageUrls(html, pageUrl, opts.max || MAX_IMAGES);
  const pageHost = new URL(pageUrl).hostname;
  const robots = new Map();
  const allowed = async (u) => {
    const host = new URL(u).hostname;
    if (host === pageHost) return true;
    if (!robots.has(host)) {
      robots.set(host, (async () => {
        try {
          const r = await fetchVetted(`${new URL(u).origin}/robots.txt`);
          return !(r.status === 200 && checks.robotsDisallowsRoot(r.body.toString("utf8")));
        } catch (e) {
          return !e.isSsrfGuard;
        }
      })());
    }
    return robots.get(host);
  };
  const budgetMs = opts.budgetMs ?? ARTWORK_BUDGET_MS;
  let timer;
  const outOfTime = new Promise((resolve) => { timer = setTimeout(resolve, budgetMs); });
  const images = await Promise.all(urls.map((url) => Promise.race([(async () => {
    try {
      if (!(await allowed(url))) return { url, skipped: "robots_txt" };
      const r = await fetchVetted(url, { maxBytes: IMAGE_MAX_BYTES });
      if (r.status !== 200 || !r.body.length) return { url, status: r.status };
      return { url: r.final_url || url, sha256: checks.sha256(r.body), bytes: r.body.length, ...inspectImage(r.body, r.truncated) };
    } catch (e) {
      return { url, error: e.isSsrfGuard ? "refused_private_address" : "fetch_failed" };
    }
  })(), outOfTime.then(() => ({ url, error: "time_limit" }))])));
  clearTimeout(timer);
  const signedAi = images.filter((i) => i.content_credentials && i.ai_generated);
  return {
    method: METHOD,
    checked_at: new Date().toISOString(),
    images_found: urls.length,
    images_read: images.filter((i) => i.format).length,
    images,
    signed_ai_images: signedAi.length,
    ai_signers: [...new Set(signedAi.map((i) => signerName(i.signer, i.test_certificate)))],
    statement: statement(images),
    signature_validated: false,
    trust_list_checked: false,
    affects_score: false,
    limits: LIMITS,
  };
}

module.exports = { artwork, inspectImage, imageUrls, statement, manifestRegion, certificates, METHOD, MAX_IMAGES };
